BEGIN;

-- --- 0. Pre-flight ----------------------------------------------------------
-- 🔴 THIS MIGRATION CREATES NO GOVERNMENT AND NO DISTRICT. Both must already
-- exist, and their ABSENCE is a hard stop rather than something to insert
-- around.
DO $$
DECLARE v_n int;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM essentials.governments WHERE geo_id = '1349008' AND type = 'City'
  ) THEN
    RAISE EXCEPTION 'bibb county: the Macon-Bibb County Government, Georgia, US row is missing -- apply the city structure half first';
  END IF;

  -- ⚠ ALWAYS PAIR geo_id WITH mtfcc AND district_type. Georgia's collision is
  -- THREE-WAY, and this wave carries a LOCAL district over the SAME ground as
  -- this COUNTY one -- so district_type is the only thing separating the tiers.
  IF NOT EXISTS (
    SELECT 1 FROM essentials.geofence_boundaries
     WHERE geo_id = '13021' AND mtfcc = 'G4020'
  ) THEN
    RAISE EXCEPTION 'bibb county: boundary 13021/G4020 is missing -- the TIGER county load must be applied first';
  END IF;

  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE geo_id = '13021' AND mtfcc = 'G4020'
     AND district_type = 'COUNTY' AND lower(state) = 'ga';
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'bibb county: expected exactly 1 existing G4020 COUNTY district 13021, found % -- this migration does not create it', v_n;
  END IF;
END $$;

-- --- 1. Chamber -------------------------------------------------------------
-- ⚠ chambers.slug is GENERATED from name_formal and cannot be inserted.
-- ⚠ The name carries "Bibb County" rather than a bare "Elected Officials",
-- because under consolidation this chamber shares a government row with two CITY
-- chambers and a bare name would read as the city's.

INSERT INTO essentials.chambers
  (government_id, name, name_formal, official_count, policy_engagement_level)
SELECT g.id, 'Bibb County Elected Officials', 'Bibb County Elected Officials', 5, 'full'
FROM essentials.governments g
WHERE g.geo_id = '1349008' AND g.type = 'City'
  AND NOT EXISTS (
    SELECT 1 FROM essentials.chambers c WHERE c.government_id = g.id AND c.name = 'Bibb County Elected Officials'
  );

