-- --- 3. Politician identity band --------------------------------------------
-- ⚠ SCOPED TO THIS MIGRATION'S OWN SUB-RANGE -1331050..-1331046, NOT to the wave
-- band -1331050..-1331036. Task 3 owns -1331045..-1331036; a guard over the whole
-- wave band would see Task 3's legitimate rows as foreign and break THIS
-- migration's re-run. That is the FL-4 correction.
DO $$
DECLARE v_n int; v_foreign text;
BEGIN
  SELECT count(*), string_agg(external_id::text, ', ' ORDER BY external_id)
    INTO v_n, v_foreign
    FROM essentials.politicians
   WHERE external_id BETWEEN -1331050 AND -1331046
     AND external_id NOT IN (-1331050, -1331049, -1331048, -1331047, -1331046);
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'bibb county: % row(s) inside this migration''s id range -1331050..-1331046 are owned by something else (%). Pick another sub-range rather than colliding.', v_n, v_foreign;
  END IF;
END $$;

CREATE TEMP TABLE bibb_seed (
  geo_id          text,
  mtfcc           text,
  district_type   text,
  office_title    text,
  ext_id          bigint,
  full_name       text,
