  name_suffix     text,
  aliases         text[],
  term_start      date,
  start_precision text,
  how_started     text,
  source          text
) ON COMMIT DROP;

INSERT INTO bibb_seed VALUES
  ('13021', 'G4020', 'COUNTY', 'Sheriff', -1331046, 'David Davis', 'David', 'Davis', NULL, NULL, '{}'::text[], DATE '2013-01-01', 'year', 'elected', 'bibbsheriff-us-live-2026-09-01 (''He was first elected Sheriff of Bibb County in November of 2012''), Georgia county officers taking office the following January + 41nbc-2020-qualifying-list (''Sheriff David Davis'') + macon-community-reporter-2025-12, which names him among the Bibb County constitutional officers changing the legal organ. ⚠ His own bio still reads ''re-elected to his third term in November of 2020'' and has not been updated for 2024 -- a stale sentence on a maintained site, used only for the FIRST election.'),
  ('13021', 'G4020', 'COUNTY', 'Clerk of Superior Court', -1331047, 'Erica Woodford', 'Erica', 'Woodford', NULL, NULL, '{}'::text[], NULL::date, 'unknown', 'elected', 'maconbibb-us-clerk-of-superior-court-live-2026-09-01 (her own office) + gasos-certified-2024-11-05 (Clerk of Superior Court on the Bibb ballot) + macon-community-reporter-2025-12 (Bibb County constitutional officers). ⚠ The 41nbc 2020 qualifying list spells her ''Eric Woodford''; that is a typo and is deliberately NOT carried as an alias, because a dropped letter is not an alternative rendering and could match the wrong person.'),
  ('13021', 'G4020', 'COUNTY', 'Tax Commissioner', -1331048, 'Wade McCord', 'Wade', 'McCord', NULL, NULL, ARRAY['S. Wade McCord', 'Samuel Wade McCord']::text[], NULL::date, 'unknown', 'elected', 'maconbibb-us-taxcommissioner121622 (quotes ''Tax Commissioner Wade McCord'') + maconbibb-us-227taxreliefseminar (''Tax Commissioner, S. Wade McCord'') + gasos-certified-2024-11-05 + 41nbc-2020-qualifying-list + macon-community-reporter-2025-12 (''tax commissioner Wade McCord, another constitutional officer''). He succeeded Thomas W. Tedders, Jr., but no source examined states when, so the start is left unwritten.'),
  ('13021', 'G4020', 'COUNTY', 'Judge of Probate Court', -1331049, 'Sarah S. Harris', 'Sarah', 'Harris', 'S.', NULL, ARRAY['Sarah Harris', 'Sarah Stevenson Harris']::text[], DATE '2013-01-01', 'year', 'elected', 'maconbibb-us-probate-court-live-2026-09-01 (''Sarah S. Harris, Judge of the Probate Court'') + macon-community-reporter-2024-08, which reports her ''re-elected to her fourth term'' and succeeding retired Judge William J. Self, having been elected unopposed in 2012 + 41nbc-2020-qualifying-list (''Judge of Probate Court: Sarah Stevenson Harris''). ⚠ Succeeding a RETIRED judge leaves open whether she first filled a remainder by appointment, so the day is not written -- only the year.'),
  ('13021', 'G4020', 'COUNTY', 'Coroner', -1331050, 'Leon Jones', 'Leon', 'Jones', NULL, NULL, '{}'::text[], NULL::date, 'unknown', 'elected', 'maconbibb-us-coroners-office-live-2026-09-01 + 41nbc-2020-qualifying-list (''Coroner: Leon Jones'') + macon-community-reporter-2026-03 (''elected six times'', current term ends 2028) + wgxa-2026-07, reporting him working a scene. 🟢 THE FRESHEST OCCUPANCY EVIDENCE IN THE WAVE, and precisely what Baldwin''s coroner lacked in GA-3. ⚠ ''Elected six times'' would arithmetically place him in office from 2005; that is arithmetic on a press phrase, not a source, and it is not written.');

-- --- 4. Payload guard -------------------------------------------------------
DO $$
DECLARE v_n int; v_dup int; v_bad text;
BEGIN
  SELECT count(*) INTO v_n FROM bibb_seed;
  IF v_n <> 5 THEN RAISE EXCEPTION 'bibb county payload: expected 5 rows, got %', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (SELECT ext_id FROM bibb_seed GROUP BY ext_id HAVING count(*) > 1) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'bibb county payload: % duplicate external_id(s)', v_dup; END IF;

  SELECT count(*) INTO v_n FROM bibb_seed WHERE ext_id NOT BETWEEN -1331050 AND -1331036;
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % out-of-band external_id(s)', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (
    SELECT geo_id, mtfcc, district_type, office_title FROM bibb_seed
    GROUP BY geo_id, mtfcc, district_type, office_title HAVING count(*) > 1
  ) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'bibb county payload: % duplicate seat key(s)', v_dup; END IF;

  -- 🔴 EVERY ROW IS district_type 'COUNTY'. The city half wrote 'LOCAL' over the
  -- SAME 254.906 sq mi, so this is the only column separating the two tiers.
  SELECT count(*) INTO v_n FROM bibb_seed WHERE district_type <> 'COUNTY';
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % row(s) are not district_type COUNTY', v_n; END IF;

  -- A date and its precision must agree in both directions.
  SELECT count(*) INTO v_n FROM bibb_seed WHERE term_start IS NULL AND start_precision <> 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % row(s) have no term_start but claim a precision', v_n; END IF;
  SELECT count(*) INTO v_n FROM bibb_seed WHERE term_start IS NOT NULL AND start_precision = 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % row(s) carry a term_start but declare it unknown', v_n; END IF;

  -- 🔴🔴 THE EXACT TUPLE SET, NOT A COUNT -- the same guard Task 3 carries.
  -- Here the likeliest corruption is the opposite of Task 3's: "tidying" the
  -- three open-ended officers into a plausible January, or promoting the two
  -- 'year' rows to 'day'. A count of dated rows cannot see either.
  SELECT count(*), string_agg(format('%s->%s/%s/%s', s.ext_id, s.term_start, s.start_precision, s.how_started), ', ' ORDER BY s.ext_id)
    INTO v_n, v_bad
    FROM bibb_seed s
   WHERE NOT EXISTS (
     SELECT 1 FROM (VALUES
    (-1331046, DATE '2013-01-01', 'year', 'elected'),
    (-1331047, NULL::date, 'unknown', 'elected'),
    (-1331048, NULL::date, 'unknown', 'elected'),
    (-1331049, DATE '2013-01-01', 'year', 'elected'),
    (-1331050, NULL::date, 'unknown', 'elected')
     ) AS e(ext_id, term_start, start_precision, how_started)
      WHERE e.ext_id = s.ext_id
        AND e.term_start IS NOT DISTINCT FROM s.term_start
        AND e.start_precision = s.start_precision
        AND e.how_started = s.how_started
   );
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'bibb county payload: % row(s) do not match the sourced (id, term_start, precision, how_started) tuple: %', v_n, v_bad;
  END IF;

  -- 🔴 EXACTLY 2 ROWS ARE DATED, AND BOTH ARE 'year' -- the Sheriff and the
  -- Judge of Probate Court, each first elected in 2012 and taking office the
  -- following January. NOT ONE is 'day': the day is not sourced for either.
  SELECT count(*) INTO v_n FROM bibb_seed WHERE term_start IS NOT NULL;
  IF v_n <> 2 THEN RAISE EXCEPTION 'bibb county payload: expected 2 dated row(s), got %', v_n; END IF;
  SELECT count(*) INTO v_n FROM bibb_seed WHERE term_start IS NOT NULL AND start_precision <> 'year';
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % dated row(s) claim a precision finer than the sourced year', v_n; END IF;

  -- 🔴 AND EXACTLY 3 ARE OPEN-ENDED. Promoting one of them to a guessed
  -- January would be a false statement about history that no end_precision
  -- exists to soften.
  SELECT count(*) INTO v_n FROM bibb_seed WHERE term_start IS NULL;
  IF v_n <> 3 THEN RAISE EXCEPTION 'bibb county payload: expected 3 open-ended row(s), got %', v_n; END IF;

  SELECT count(*) INTO v_n FROM bibb_seed
   WHERE how_started NOT IN ('elected','appointed','succeeded','redistricted','unknown');
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % row(s) carry a how_started the CHECK will refuse', v_n; END IF;

  -- ⚠ alternate_names is NOT NULL DEFAULT '{}'. Emit an empty array, never NULL.
  SELECT count(*) INTO v_n FROM bibb_seed WHERE aliases IS NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % row(s) carry a NULL aliases array', v_n; END IF;

  SELECT count(*) INTO v_n FROM bibb_seed s
   WHERE (SELECT count(*) FROM essentials.offices o
            JOIN essentials.districts d ON d.id = o.district_id
           WHERE d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
             AND d.district_type = s.district_type AND lower(d.state) = 'ga'
             AND o.title = s.office_title) <> 1;
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county payload: % seat(s) do not resolve to exactly one office', v_n; END IF;
END $$;

-- --- 5. Politicians ---------------------------------------------------------
-- 🔴 IDENTITY IS KEYED ON external_id, NEVER ON NAME. All 5 were checked against
-- production by EXACT match and none matched. The surname near misses are FEC
-- committee ALLCAPS junk plus genuinely different people. A name-based guard is
-- what seated a Colorado senator and a Utah treasurer in the Georgia General
-- Assembly, caught at GA-2 before it happened.
INSERT INTO essentials.politicians
  (external_id, full_name, first_name, last_name, middle_initial, name_suffix,
   alternate_names, is_incumbent, is_active, data_source)
SELECT s.ext_id, s.full_name, s.first_name, s.last_name,
       nullif(s.middle_initial, ''), nullif(s.name_suffix, ''),
       s.aliases, true, true, s.source
FROM bibb_seed s
ON CONFLICT (external_id) DO NOTHING;

-- --- 6. Occupancy -----------------------------------------------------------
-- 🔴 TWO PATHS, AND THE SECOND ONE IS NOT A SHORTCUT. seat_officeholder()
-- REFUSES a NULL term_start, and 3 of these 5 have no published start of
-- any kind. Direct insert is safe ONLY into an office with zero existing term
-- rows; the guard REFUSES rather than guesses if that stops being true.
--
-- ⚠ Task 3 needed only the helper path, because every city official has a real
--   date. That difference is a fact about what Macon-Bibb publishes, not a
--   choice -- and it is why the direct path still has to exist and be guarded.
DO $$
DECLARE r record; v_seated int := 0; v_blank int := 0; v_prior int;
BEGIN
  FOR r IN
    SELECT s.term_start, s.start_precision, s.how_started, s.source,
           o.id AS office_id, p.id AS politician_id
      FROM bibb_seed s
      JOIN essentials.districts d
        ON d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
       AND d.district_type = s.district_type AND lower(d.state) = 'ga'
      JOIN essentials.offices o ON o.district_id = d.id AND o.title = s.office_title
      JOIN essentials.politicians p ON p.external_id = s.ext_id
     WHERE NOT EXISTS (
       SELECT 1 FROM essentials.office_terms t
        WHERE t.office_id = o.id AND t.politician_id = p.id
     )
  LOOP
    IF r.term_start IS NOT NULL THEN
      PERFORM essentials.seat_officeholder(
        r.office_id, r.politician_id, r.term_start, r.source, r.how_started, r.start_precision
      );
      v_seated := v_seated + 1;
    ELSE
      IF r.start_precision <> 'unknown' THEN
        RAISE EXCEPTION 'bibb county: office % has no term_start but claims precision % -- refusing', r.office_id, r.start_precision;
      END IF;
      SELECT count(*) INTO v_prior FROM essentials.office_terms t WHERE t.office_id = r.office_id;
      IF v_prior <> 0 THEN
        RAISE EXCEPTION 'bibb county: office % already carries % term row(s), so an undated open term cannot be inserted directly -- close the predecessor and give this person a real date', r.office_id, v_prior;
      END IF;
      INSERT INTO essentials.office_terms
        (office_id, politician_id, term_start, term_end, start_precision, how_started, source)
      VALUES (r.office_id, r.politician_id, NULL, NULL, 'unknown', r.how_started, r.source);
      v_blank := v_blank + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'bibb county: seated % dated officer(s) via seat_officeholder(), % with an honest unknown start', v_seated, v_blank;
END $$;

-- --- 7. Post-verify gate ----------------------------------------------------
-- 🔴 SCOPED TO THIS ONE CHAMBER, never to the government: the same government
-- row carries the two CITY chambers, and a government-wide count would couple
-- this migration to them in both directions.
DO $$
DECLARE v_gov uuid; v_ch uuid; v_n int;
BEGIN
  SELECT id INTO v_gov FROM essentials.governments
   WHERE geo_id = '1349008' AND type = 'City';
  IF v_gov IS NULL THEN RAISE EXCEPTION 'bibb county: the government row is missing'; END IF;

  SELECT id INTO v_ch FROM essentials.chambers
   WHERE government_id = v_gov AND name = 'Bibb County Elected Officials' AND official_count = 5;
  IF v_ch IS NULL THEN RAISE EXCEPTION 'bibb county: the Bibb County Elected Officials chamber is missing or carries the wrong official_count'; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices WHERE chamber_id = v_ch;
  IF v_n <> 5 THEN RAISE EXCEPTION 'bibb county: expected 5 offices in the chamber, got %', v_n; END IF;

  -- 🔴🔴 THE TIERS MUST NOT HAVE CROSSED. The citywide LOCAL district covers the
  -- SAME 254.906 sq mi as this COUNTY one, so an office landing on the wrong one
  -- would still resolve at every address in Macon and look entirely correct --
  -- only the tier would be wrong, and nothing would error. This is the MIRROR of
  -- the gate the structure half applies to the ten city seats.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE o.chamber_id = v_ch
     AND NOT (d.geo_id = '13021' AND d.mtfcc = 'G4020' AND d.district_type = 'COUNTY');
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county: % county office(s) do not sit on 13021/G4020 COUNTY -- the tiers crossed', v_n; END IF;

  -- And the countywide district was not duplicated by this migration.
  SELECT count(*) INTO v_n FROM essentials.districts
   WHERE geo_id = '13021' AND mtfcc = 'G4020' AND district_type = 'COUNTY';
  IF v_n <> 1 THEN RAISE EXCEPTION 'bibb county: expected exactly 1 Bibb County COUNTY district, got %', v_n; END IF;

  -- ⚠ COUNT THIS MIGRATION'S OWN IDS, NOT THE WHOLE BAND.
  SELECT count(*) INTO v_n FROM essentials.politicians WHERE external_id IN (-1331050, -1331049, -1331048, -1331047, -1331046);
  IF v_n <> 5 THEN RAISE EXCEPTION 'bibb county: expected 5 of this migration''s politicians, got %', v_n; END IF;

  -- 🔴 count(och.politician_id), NOT count(*): office_current_holder LEFT JOINs
  -- from offices, so a vacancy is a NULL politician_id and count(*) passes
  -- VACUOUSLY on an entirely unseated chamber.
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE o.chamber_id = v_ch;
  IF v_n <> 5 THEN RAISE EXCEPTION 'bibb county: expected 5 seated officers, found %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices WHERE chamber_id = v_ch AND is_vacant = true;
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county: % officer seat(s) flagged vacant, expected 0', v_n; END IF;

  -- The 3 undated terms are open-ended at 'unknown', with NO term_end: a
  -- future term_end makes a seat silently self-vacate on a date nobody watches.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id IN (-1331050, -1331048, -1331047)
     AND (t.start_precision <> 'unknown' OR t.term_start IS NOT NULL OR t.term_end IS NOT NULL);
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county: % term row(s) that should be open-ended unknown are not', v_n; END IF;

  -- 🔴 NOT ONE of this migration's terms carries a term_end.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id IN (-1331050, -1331049, -1331048, -1331047, -1331046) AND t.term_end IS NOT NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county: % term row(s) carry a term_end -- none may', v_n; END IF;

  -- And each dated one carries exactly the date that was sourced, at the
  -- precision the source actually supports, asserted INDIVIDUALLY.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331046
     AND t.term_start = DATE '2013-01-01'
     AND t.start_precision = 'year'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'bibb county: David Davis (-1331046) does not hold exactly one OPEN term starting 2013-01-01 at year precision, got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331049
     AND t.term_start = DATE '2013-01-01'
     AND t.start_precision = 'year'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'bibb county: Sarah S. Harris (-1331049) does not hold exactly one OPEN term starting 2013-01-01 at year precision, got %', v_n; END IF;

  -- No officer seat may be left with no term row: that is the invisible-office
  -- failure, and nothing else errors.
  SELECT count(*) INTO v_n FROM essentials.offices o
   WHERE o.chamber_id = v_ch
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = o.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'bibb county: % officer seat(s) carry no office_terms row and are invisible', v_n; END IF;

  RAISE NOTICE 'bibb county OK: 1 chamber, 5 offices, 5 officers seated, 0 vacancies, 0 districts created (2 dated at year, 3 open-ended unknown)';
END $$;

COMMIT;
